"""
Embeddable Python ships in isolated mode and ignores PYTHONPATH. This
sitecustomize is auto-imported by site.py (enabled in python312._pth) and
restores the normal behavior of treating the current working directory as
an importable package root — so scripts can import their siblings, like a
standard `python main.py` invocation would.
"""
import os
import sys

cwd = os.getcwd()
if cwd not in sys.path:
    sys.path.insert(0, cwd)
